kanban.script:

$(document).ready(function() {
    console.log('Cash Flow Charts: JavaScript loaded');
    console.log('Chart.js available:', typeof Chart !== 'undefined');
    
    // Function to render charts for all kanban cards
    function renderCashFlowCharts() {
        console.log('Cash Flow Charts: Starting chart rendering');
        
        $('.oe_kanban_card').each(function() {
            var card = $(this);
            var chartDataRaw = card.data('chart');
            var recordId = card.data('record-id');
            
            console.log('Processing card:', recordId, 'Data:', chartDataRaw);
            
            if (chartDataRaw && recordId) {
                try {
                    // Parse the dashboard_graph format data
                    var dashboardData = JSON.parse(chartDataRaw);
                    var chartId = 'chart_' + recordId;
                    var canvas = document.getElementById(chartId);
                    
                    console.log('Chart ID:', chartId, 'Canvas found:', !!canvas);
                    
                    if (canvas && dashboardData.length > 0 && dashboardData[0].values) {
                        // Destroy existing chart if exists
                        var existingChart = Chart.getChart(canvas);
                        if (existingChart) {
                            existingChart.destroy();
                        }
                        
                        // Convert dashboard_graph format to Chart.js format
                        var values = dashboardData[0].values;
                        var labels = values.map(function(item) { return item.label; });
                        var data = values.map(function(item) { return item.value; });
                        
                        // Determine chart color based on balance trend
                        var borderColor = '#3498db';
                        var backgroundColor = 'rgba(52, 152, 219, 0.1)';
                        
                        console.log('Creating chart with data points:', data.length);
                        
                        // Test if Chart.js is available
                        if (typeof Chart === 'undefined') {
                            console.error('Chart.js is not loaded!');
                            return;
                        }
                        
                        // Create new chart
                        var chart = new Chart(canvas, {
                            type: 'line',
                            data: {
                                labels: labels,
                                datasets: [{
                                    data: data,
                                    borderColor: borderColor,
                                    backgroundColor: backgroundColor,
                                    borderWidth: 2,
                                    fill: true,
                                    tension: 0.3,
                                    pointRadius: 2,
                                    pointHoverRadius: 4
                                }]
                            },
                            options: {
                                responsive: true,
                                maintainAspectRatio: false,
                                plugins: {
                                    legend: {
                                        display: false
                                    },
                                    tooltip: {
                                        mode: 'index',
                                        intersect: false,
                                        callbacks: {
                                            title: function(context) {
                                                return 'Date: ' + context[0].label;
                                            },
                                            label: function(context) {
                                                return 'Balance: ' + context.parsed.y.toLocaleString();
                                            }
                                        }
                                    }
                                },
                                scales: {
                                    x: {
                                        display: true,
                                        grid: {
                                            display: false
                                        },
                                        ticks: {
                                            maxTicksLimit: 5
                                        }
                                    },
                                    y: {
                                        display: false,
                                        beginAtZero: false
                                    }
                                },
                                interaction: {
                                    intersect: false,
                                    mode: 'index'
                                }
                            }
                        });
                        
                        console.log('Chart created successfully for record:', recordId);
                    } else {
                        console.log('Skipping chart - missing canvas or data:', {
                            canvas: !!canvas,
                            dataLength: dashboardData.length,
                            hasValues: dashboardData[0] && dashboardData[0].values
                        });
                    }
                } catch (e) {
                    console.error('Error rendering chart for record ' + recordId + ':', e);
                }
            } else {
                console.log('Skipping card - missing data or record ID:', {
                    hasData: !!chartDataRaw,
                    recordId: recordId
                });
            }
        });
        
        console.log('Cash Flow Charts: Finished processing all cards');
    }
    
    // Initial chart rendering with longer delay
    setTimeout(renderCashFlowCharts, 500);
    
    // Re-render charts when kanban is refreshed
    $(document).on('DOMNodeInserted', '.o_kanban_view', function() {
        setTimeout(renderCashFlowCharts, 500);
    });
});

form.script:

// Get context from Odoo's action context (simple approach)
$(document).ready(function() {
    console.log('Form view loading...');
    
    // Try multiple ways to get context
    var context = {
        period_type: 'all',
        date_from: null,
        date_to: null,
        period_label: 'All Time'
    };
    
    // Method 1: URL parameters
    var urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('period_type')) {
        context.period_type = urlParams.get('period_type');
        context.date_from = urlParams.get('date_from');
        context.date_to = urlParams.get('date_to');
        context.period_label = urlParams.get('period_label');
    }
    
    // Method 2: Session storage (set by dashboard component)
    try {
        var storedContext = sessionStorage.getItem('cash_flow_period_context');
        if (storedContext) {
            var parsedContext = JSON.parse(storedContext);
            // Check if it's recent (within last 30 seconds)
            if (Date.now() - parsedContext.timestamp < 30000) {
                context = parsedContext;
                console.log('Using session storage context:', context);
            }
        }
    } catch (e) {
        console.log('Could not read session storage:', e);
    }
    
    // Method 3: Check window context
    if (window.odoo && window.odoo.session_info) {
        try {
            var user_context = window.odoo.session_info.user_context || {};
            if (user_context.period_type) {
                context.period_type = user_context.period_type;
                context.date_from = user_context.date_from;
                context.date_to = user_context.date_to;
                context.period_label = user_context.period_label;
            }
        } catch (e) {
            console.log('Could not read window context:', e);
        }
    }
    
    console.log('Final form context:', context);
    
    // Update display
    updatePeriodDisplay(context);
    loadIndividualBalances();
    loadPeriodSummary();
    
    // Clear session storage after use
    try {
        sessionStorage.removeItem('cash_flow_period_context');
    } catch (e) {
        // Ignore
    }
});

function updatePeriodDisplay(context) {
    var periodLabel = context.period_label || formatPeriodLabel(context.period_type, context.date_from, context.date_to);
    
    if (context.period_type !== 'all' || context.date_from || context.date_to) {
        // Show period banner
        $('#period_info_banner').show();
        $('#period_label_display').text(periodLabel);
        
        // Update header text
        $('.oe_title h1').after('<p class="text-muted mb-0"><i class="fa fa-calendar text-primary"/> Period: <strong>' + periodLabel + '</strong></p>');
        
        // Change balance labels to indicate period filtering
        $('label[for="current_balance"]').text('Balance for Selected Period');
        $('label[for="balance_display"]').text('Formatted Balance (Period)');
    }
}

function formatPeriodLabel(periodType, dateFrom, dateTo) {
    if (!periodType || periodType === 'all') {
        return 'All Time';
    } else if (periodType === 'custom' && dateFrom && dateTo) {
        return dateFrom + ' to ' + dateTo;
    } else if (dateFrom && dateTo) {
        try {
            var start = new Date(dateFrom).toLocaleDateString('en-US', { 
                month: 'short', day: 'numeric' 
            });
            var end = new Date(dateTo).toLocaleDateString('en-US', { 
                month: 'short', day: 'numeric', year: 'numeric' 
            });
            return start + ' - ' + end;
        } catch (e) {
            return dateFrom + ' to ' + dateTo;
        }
    } else {
        return periodType.replace('_', ' ').replace(/\b\w/g, l => l.toUpperCase());
    }
}

function loadIndividualBalances() {
    var individualBalancesField = $('input[name="individual_balances"]');
    if (individualBalancesField.length > 0) {
        var balancesData = individualBalancesField.val();
        console.log('Individual balances raw data:', balancesData);
        
        if (balancesData) {
            try {
                var balances = JSON.parse(balancesData);
                console.log('Parsed individual balances:', balances);
                var container = $('#individual_balances_container');
                var html = '';
                
                if (balances.length > 0) {
                    html += '<div class="row">';
                    balances.forEach(function(balance) {
                        var colorClass = balance.balance > 0 ? 'border-success' : 
                                       (balance.balance < 0 ? 'border-danger' : 'border-secondary');
                        var textClass = balance.balance > 0 ? 'text-success' : 
                                      (balance.balance < 0 ? 'text-danger' : 'text-secondary');
                        
                        html += '<div class="col-md-6 col-12 mb-3">';
                        html += '<div class="card ' + colorClass + '">';
                        html += '<div class="card-header bg-light d-flex justify-content-between align-items-center">';
                        html += '<h6 class="mb-0 text-primary">' + balance.code + '</h6>';
                        html += '<span class="badge bg-light text-dark">Account</span>';
                        html += '</div>';
                        html += '<div class="card-body">';
                        html += '<p class="card-text text-muted small mb-2">' + balance.name + '</p>';
                        html += '<h5 class="card-text ' + textClass + ' mb-0">' + balance.formatted_balance + '</h5>';
                        html += '</div>';
                        html += '</div>';
                        html += '</div>';
                    });
                    html += '</div>';
                    
                } else {
                    html = '<div class="alert alert-warning">';
                    html += '<i class="fa fa-exclamation-triangle"/> ';
                    html += 'No individual account data available for the selected period.';
                    html += '</div>';
                }
                
                container.html(html);
            } catch (e) {
                console.error('Error parsing individual balances:', e);
                $('#individual_balances_container').html(
                    '<div class="alert alert-danger">' +
                    '<i class="fa fa-exclamation-circle"/> Error loading individual account balances.' +
                    '</div>'
                );
            }
        } else {
            $('#individual_balances_container').html(
                '<div class="alert alert-info">' +
                '<i class="fa fa-info-circle"/> No balance data available for the selected period.' +
                '</div>'
            );
        }
    } else {
        $('#individual_balances_container').html(
            '<div class="alert alert-warning">' +
            '<i class="fa fa-question-circle"/> Balance data field not found.' +
            '</div>'
        );
    }
}

function loadPeriodSummary() {
    var balancesField = $('input[name="individual_balances"]').val();
    
    if (balancesField) {
        try {
            var balances = JSON.parse(balancesField);
            var totalBalance = balances.reduce((sum, acc) => sum + acc.balance, 0);
            var positiveCount = balances.filter(acc => acc.balance > 0).length;
            var negativeCount = balances.filter(acc => acc.balance < 0).length;
            var accountCount = balances.length;
            
            $('#total_balance_display').text('₺' + totalBalance.toLocaleString());
            $('#account_count_display').text(accountCount);
            $('#positive_accounts_display').text(positiveCount);
            $('#negative_accounts_display').text(negativeCount);
            
            // Show summary section
            $('#period_summary_section').show();
            
        } catch (e) {
            console.error('Error calculating summary:', e);
        }
    }
}
